import{_ as s,o as i,c as a,a5 as t}from"./chunks/framework.B6tQOu6W.js";const c=JSON.parse(`{"title":"L'outillage du développeur","description":"","frontmatter":{},"headers":[],"relativePath":"cheatsheets/web/index.md","filePath":"cheatsheets/web/index.md","lastUpdated":1761649295000}`),n={name:"cheatsheets/web/index.md"};function l(r,e,o,p,d,u){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="l-outillage-du-developpeur" tabindex="-1">L&#39;outillage du développeur <a class="header-anchor" href="#l-outillage-du-developpeur" aria-label="Permalink to &quot;L&#39;outillage du développeur&quot;">​</a></h1><p>Préparer son environnement de développement est une étape essentielle pour tout développeur web. Selon votre système d&#39;exploitation, les étapes peuvent varier légèrement.</p><p>Dans ce support, vous trouverez les instructions pour configurer un environnement de développement web sous Windows, Linux et macOS.</p><h2 id="global" tabindex="-1">Global <a class="header-anchor" href="#global" aria-label="Permalink to &quot;Global&quot;">​</a></h2><p>Pour coder vous aurez besoin d&#39;un éditeur de texte ou d&#39;un IDE. Voici quelques recommandations populaires :</p><ul><li><a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">Visual Studio Code</a> - Un éditeur de code léger et puissant, avec de nombreuses extensions pour le développement web. <ul><li>Extensions recommandées : <ul><li><a href="https://marketplace.visualstudio.com/items?itemName=bmewburn.vscode-intelephense-client" target="_blank" rel="noreferrer">PHP Intelephense</a> - Fournit l&#39;autocomplétion, la vérification de syntaxe et d&#39;autres fonctionnalités pour PHP.</li><li><a href="https://marketplace.visualstudio.com/items?itemName=MehediDracula.php-namespace-resolver" target="_blank" rel="noreferrer">PHP Namespace Resolver</a> - Aide à gérer les namespaces en PHP.</li><li><a href="https://marketplace.visualstudio.com/items?itemName=esbenp.prettier-vscode" target="_blank" rel="noreferrer">Prettier - Code formatter</a> - Un formateur de code pour divers langages, y compris JavaScript, HTML et CSS.</li><li><a href="https://marketplace.visualstudio.com/items?itemName=bradlc.vscode-tailwindcss" target="_blank" rel="noreferrer">Tailwind CSS IntelliSense</a> - Fournit l&#39;autocomplétion et la documentation pour Tailwind CSS.</li></ul></li></ul></li><li><a href="https://www.jetbrains.com/webstorm/" target="_blank" rel="noreferrer">WebStorm</a> - Un IDE complet pour le développement web, avec des fonctionnalités avancées.</li><li><a href="https://www.jetbrains.com/phpstorm/" target="_blank" rel="noreferrer">PHPStorm</a> - Un IDE dédié au développement PHP, avec des outils intégrés pour le débogage et le testing.</li><li><a href="https://neovim.io/" target="_blank" rel="noreferrer">NeoVim</a> - Un éditeur de texte moderne basé sur Vim, très personnalisable et extensible. Très puissant une fois maîtrisé.</li></ul><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">2025 ? Solution WSL !</p><p>WSL permet d&#39;obtenir un environnement Linux directement sous Windows, idéal pour le développement.</p><p>Un bon point de départ est <strong>Alpine</strong> avec l&#39;ensemble des éléments nécessaires au développement web.</p><p>Il s’agit d’un fork de <strong>AlpineWSL</strong>, enrichi de nombreux outils déjà installés :</p><p><a href="https://github.com/c4software/AlpineWSL-web/releases" target="_blank" rel="noreferrer">https://github.com/c4software/AlpineWSL-web/releases</a></p><p>Après installation (<strong>décompression</strong> et lancement de <code>Alpine.exe</code>), vous disposez d’un terminal Linux avec les outils suivants préinstallés :</p><ul><li>PHP</li><li>Composer</li><li>Node.js et npm</li><li>Python</li><li>Git</li><li>Vim</li></ul><p>Vous avez ainsi un environnement Linux complet, léger et prêt à l’emploi, comprenant les principaux langages et outils du développement web (PHP, Node.js, Python, Composer, Git, Vim, etc.).</p><p><strong>PS :</strong> <code>apk</code> est le gestionnaire de paquets</p></div><p>👋 Si vous avez fait le choix de WSL ? Pas besoin de faire la suite.</p><p>Pour commencer à développer sous Windows, il est recommandé d&#39;installer un environnement comprenant les outils essentiels comme un serveur web, un interpréteur de langage (PHP, Node.js, Python...), et un gestionnaire de paquets.</p><ul><li><a href="https://github.com/abbodi1406/vcredist/releases" target="_blank" rel="noreferrer">Installation du VCRedist</a>.</li><li><a href="https://wampserver.aviatechno.net/" target="_blank" rel="noreferrer">Installation de Wamp.</a>.</li><li>Installer Wamp, et vérifier que celui-ci fonctionne correctement.</li><li>Gitbash : <a href="https://git-scm.com/download/win" target="_blank" rel="noreferrer">Téléchargement</a> et installation.</li></ul><h3 id="installer-un-gestionnaire-de-paquets" tabindex="-1">Installer un gestionnaire de paquets <a class="header-anchor" href="#installer-un-gestionnaire-de-paquets" aria-label="Permalink to &quot;Installer un gestionnaire de paquets&quot;">​</a></h3><ul><li><a href="https://getcomposer.org/Composer-Setup.exe" target="_blank" rel="noreferrer">Composer pour PHP</a></li><li><a href="https://nodejs.org/" target="_blank" rel="noreferrer">npm pour Node.js</a></li><li>Vérifiez que la commande est bien disponible dans un nouveau terminal (<code>composer</code>, <code>npm</code>, etc.).</li></ul><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><p>Sous Linux, il suffit d&#39;installer les langages et outils nécessaires via le gestionnaire de paquets de votre distribution (ex : <code>apt</code>, <code>dnf</code>, <code>pacman</code>, etc.). Exemple pour installer PHP, Node.js et Python :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nodejs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vim</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Pour installer Composer (pour PHP) :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://getcomposer.org/installer</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> php</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> composer.phar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/composer</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/composer</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><p>Sous macOS, la commande <code>brew</code> permet d&#39;installer facilement les outils nécessaires :</p><ul><li>Installer <a href="https://brew.sh/" target="_blank" rel="noreferrer">Homebrew</a> si ce n&#39;est pas déjà fait.</li><li>Installer les langages et outils nécessaires :</li></ul><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vim</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>`,22)])])}const m=s(n,[["render",l]]);export{c as __pageData,m as default};
